const BY_KEY = new Map(COUNTRIES.map((c) => [c.key, c]));

/** Nom du pays (clé serveur « Japan ») dans la langue de l'app (« Japon »), sinon tel quel. */
export function countryName(key: string | null | undefined, lang: string): string {
  if (!key) return '';
  const c = BY_KEY.get(key);
  return (c && (c.names[lang] || c.names.en)) || key;
}

export function countryFlag(key: string | null | undefined): string {
  return (key && BY_KEY.get(key)?.flag) || '';
}
